static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 读取输入形状，假设为三维 [d0, d1, d2]
    const gert::Shape* inShape = context->GetInputShape(0);
    if (inShape->GetOriginShape().GetDimNum() != 3) {
        // 简化示例：仅支持3D输入
        return ge::GRAPH_FAILED;
    }
    int64_t d0 = inShape->GetOriginShape().GetDim(0);
    int64_t d1 = inShape->GetOriginShape().GetDim(1);
    int64_t d2 = inShape->GetOriginShape().GetDim(2);

    // 本示例固定按维度1执行argmin（与给定模型中的dim=1一致）
    const int32_t axis = 1;
    const uint32_t inner_axis1 = static_cast<uint32_t>(d1); // 被约简的维度长度
    const uint32_t outter_per_call = 1; // TopK每次只处理1行

    // TopK参数
    const uint32_t k = 1;
    const bool isLargest = false;       // argmin => isLargest=false
    const bool isInitIndex = false;     // 索引由TopK自动生成
    auto platformInfo = context->GetPlatformInfo();
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);

    // 选择TopK模式：若inner为32可用NSMALL，否则NORMAL
    AscendC::TopKMode mode_axis1 = (inner_axis1 == 32) ? AscendC::TopKMode::TOPK_NSMALL : AscendC::TopKMode::TOPK_NORMAL;

    // 计算TopK tiling（按行(outter=1)）
    optiling::TopkTiling topkTilingAxis1;
    bool ok = AscendC::TopKTilingFunc(ascendcPlatform,
                                      inner_axis1,
                                      outter_per_call,
                                      k,
                                      /*dataTypeSize=*/4, // float
                                      isInitIndex,
                                      mode_axis1,
                                      isLargest,
                                      topkTilingAxis1);
    if (!ok) {
        return ge::GRAPH_FAILED;
    }

    // 获取临时空间范围并采用最小值
    uint32_t maxTmp = 0, minTmp = 0;
    AscendC::GetTopKMaxMinTmpSize(ascendcPlatform,
                                  inner_axis1,
                                  outter_per_call,
                                  /*isReuseSource=*/false,
                                  isInitIndex,
                                  mode_axis1,
                                  isLargest,
                                  /*dataTypeSize=*/4,
                                  maxTmp,
                                  minTmp);

    // 设置BlockDim（示例）
    context->SetBlockDim(8);

    ArgminOverADimensionCustomTilingData tiling;
    tiling.set_d0(static_cast<int32_t>(d0));
    tiling.set_d1(static_cast<int32_t>(d1));
    tiling.set_d2(static_cast<int32_t>(d2));

    tiling.set_axis(axis);
    tiling.set_k(k);
    tiling.set_islargest(isLargest);
    tiling.set_isinitindex(isInitIndex);

    tiling.set_tmpsize_axis1(minTmp);
    tiling.set_topkTilingAxis1(topkTilingAxis1);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0; // 本算子无需workspace
    return ge::GRAPH_SUCCESS;
}
}


